// Demonstrating virtual memory concepts in Node.js
const v8 = require('v8');

// 1. Memory overcommit: allocate a large buffer without immediately
//    touching every byte — the OS only maps physical pages on first access
const SIZE = 512 * 1024 * 1024; // 512 MB virtual allocation
const buf = Buffer.allocUnsafe(SIZE); // virtual pages reserved, not all physical

const before = process.memoryUsage();
console.log('RSS before touch:', (before.rss / 1e6).toFixed(1), 'MB');

// 2. Touch pages sequentially — each 4096-byte stride triggers a page fault
//    the first time, causing the OS to map a physical frame
const PAGE_SIZE = 4096;
for (let i = 0; i < SIZE; i += PAGE_SIZE) {
  buf[i] = 0xff; // first write to each page triggers a minor page fault
}

const after = process.memoryUsage();
console.log('RSS after touch:', (after.rss / 1e6).toFixed(1), 'MB');
// RSS grows only as pages are actually accessed — virtual memory in action

// 3. Heap stats: V8 manages its own virtual heap within the process's VAS
const stats = v8.getHeapStatistics();
console.log('V8 heap size limit:', (stats.heap_size_limit / 1e6).toFixed(0), 'MB');

// Virtual memory layout of a typical 64-bit process (conceptual)
const virtualAddressSpace = {
  // High addresses — kernel space (user code cannot access)
  kernelSpace:   '0xFFFF800000000000 - 0xFFFFFFFFFFFFFFFF',

  // User space regions (low to high):
  codeSegment:   '0x400000           (ELF .text, .rodata)',
  dataSegment:   '0x...              (.data, .bss — globals)',
  heap:          '0x...              (malloc/new — grows upward)',
  mmapRegion:    '0x...              (shared libs, mmap files)',
  stack:         '0x7FFFFFFFFFFF     (grows downward)',
};

// Address translation formula:
// physical_address = frame_number * PAGE_SIZE + page_offset
// where:
//   page_number = virtual_address >> 12    (top bits)
//   page_offset = virtual_address & 0xFFF  (bottom 12 bits for 4KB pages)
const PAGE_SIZE = 4096; // 2^12
function translateAddress(virtualAddr, pageTable) {
  const pageNumber = virtualAddr >> 12;
  const offset     = virtualAddr & (PAGE_SIZE - 1);
  const frame      = pageTable[pageNumber]; // OS lookup
  return frame * PAGE_SIZE + offset;
}
